  border:1px solid var(--ap-line) !important;
  border-radius:var(--ap-r) !important;
  box-shadow:none !important; text-shadow:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  font-family:var(--ap-font) !important; color:var(--ap-ink) !important;
}
.chat-detail-screen .bubble-them-custom :is(span,p,div,a,strong,em):not(.msg-translation-btn):not(.msg-translation-btn *),
.chat-detail-screen .bubble-me-custom :is(span,p,div,a,strong,em):not(.msg-translation-btn):not(.msg-translation-btn *){
  color:var(--ap-ink) !important;
}
.bubble-them-custom > *, .bubble-me-custom > *{ margin-top:0 !important; margin-bottom:0 !important; }
.bubble-them-custom :is(p,span,div):not(.msg-translation-wrapper):not(.msg-translation-btn):not(.msg-translation-btn *),
.bubble-me-custom :is(p,span,div):not(.msg-translation-wrapper):not(.msg-translation-btn):not(.msg-translation-btn *){
