}
.bubble-them-custom, .bubble-me-custom,
.bubble-them-custom :is(p,span,div), .bubble-me-custom :is(p,span,div){
  word-break:normal !important; overflow-wrap:anywhere !important;
  line-break:auto !important; text-wrap:wrap !important;
}
.bubble-them-custom::before, .bubble-me-custom::before,
.bubble-them-custom::after,  .bubble-me-custom::after{ content:none !important; display:none !important; }

/* 尾气泡:两个小圆圈尾巴(颜色跟随气泡,夜间自动变) */
.chat-detail-screen .msg-bubble-wrapper.msg-them:is(.is-last, .is-single):not(:has(.msg-reply-block-detached)) .bubble-them-custom:not(:has(img, video, [class*="card"])):not([class*="card"])::after,
.chat-detail-screen .msg-bubble-wrapper.msg-me:is(.is-last, .is-single):not(:has(.msg-reply-block-detached)) .bubble-me-custom:not(:has(img, video, [class*="card"])):not([class*="card"])::after{
  content:"" !important; display:block !important; position:absolute !important;
  top:100% !important; bottom:auto !important;
  width:20px !important; height:18px !important; margin-top:1px !important;
  pointer-events:none !important; z-index:1 !important;
  background:
    radial-gradient(circle at 14px 5px, var(--ap-bubble) 0 3.6px, var(--ap-line) 3.8px 4.6px, transparent 4.9px),
    radial-gradient(circle at 5.5px 13px, var(--ap-bubble) 0 2px, var(--ap-line) 2.2px 3px, transparent 3.3px) !important;
}
.chat-detail-screen .msg-bubble-wrapper.msg-them:is(.is-last, .is-single) .bubble-them-custom::after{
  left:2px !important; right:auto !important; transform:none !important;
}
.chat-detail-screen .msg-bubble-wrapper.msg-me:is(.is-last, .is-single) .bubble-me-custom::after{
  right:2px !important; left:auto !important; transform:scaleX(-1) !important;
}

/* 图片 / 卡片类气泡:去掉气泡外观 */
.chat-detail-screen :is(.bubble-them-custom,.bubble-me-custom):has(
  img:not(:is(.msg-reply-block, .msg-reply-block-detached) img),
  video:not(:is(.msg-reply-block, .msg-reply-block-detached) video),
  [class*="card"]:not(:is(.msg-reply-block, .msg-reply-block-detached) [class*="card"])
){
  background:transparent !important; border:0 !important; box-shadow:none !important; padding:0 !important;
}

/* ==========================================================
   3. 头像  只在尾消息显示 · 放在尾气泡下方 · 32px
   ========================================================== */
.chat-detail-screen .msg-bubble-wrapper .nuo-avatar-frame{ display:none !important; }
.chat-detail-screen .msg-bubble-wrapper:not(.is-last):not(.is-single) :is(.msg-avatar-them-container, .msg-avatar-me-container, .msg-avatar-container, .msg-avatar-them-ghost){
  display:none !important;
}
.chat-detail-screen .msg-bubble-wrapper:is(.is-last, .is-single) :is(.msg-avatar-them-container, .msg-avatar-me-container, .msg-avatar-container){
  display:block !important; visibility:visible !important;
  position:absolute !important; top:auto !important;
  bottom:var(--ap-group-gap) !important;
  width:var(--ap-av) !important; height:var(--ap-av) !important; min-width:0 !important;
  margin:0 !important; padding:0 !important; transform:none !important;
  z-index:2 !important;
}
.chat-detail-screen .msg-bubble-wrapper.msg-them:is(.is-last, .is-single) :is(.msg-avatar-them-container, .msg-avatar-container){
  left:0 !important; right:auto !important;
}
.chat-detail-screen .msg-bubble-wrapper.msg-me:is(.is-last, .is-single) :is(.msg-avatar-me-container, .msg-avatar-container){
  right:0 !important; left:auto !important;
}
.chat-detail-screen .msg-bubble-wrapper:is(.is-last, .is-single) .msg-avatar-them-ghost{
  position:absolute !important; left:0 !important; bottom:var(--ap-group-gap) !important; top:auto !important;
  width:var(--ap-av) !important; height:var(--ap-av) !important;
}
:is(.msg-avatar-them-inner, .msg-avatar-me-inner, .msg-avatar-custom){
  width:var(--ap-av) !important; height:var(--ap-av) !important; min-width:0 !important;
  border-radius:50% !important; overflow:hidden !important;
  border:1px solid var(--ap-line) !important; box-shadow:none !important;
  object-fit:cover !important; background-size:cover !important; background-position:center !important;
}
:is(.msg-avatar-them-inner, .msg-avatar-me-inner) img{
  width:100% !important; height:100% !important; border-radius:50% !important; object-fit:cover !important;
}

/* ==========================================================
   4. 时间戳 / 日期 / 撤回  淡灰小字
   ========================================================== */
:is(.timestamp-custom, .date-divider-custom, .msg-recalled .msg-system){
  display:block !important; margin:10px auto !important; padding:0 !important;
  background:transparent !important; border:0 !important; box-shadow:none !important;
  color:var(--ap-sub) !important; font:400 12px/16px var(--ap-font) !important;
  text-shadow:none !important; text-align:center !important;
}
.msg-recalled .msg-system *{ color:var(--ap-sub) !important; }
.msg-status-custom{ color:var(--ap-sub) !important; text-shadow:none !important; }

/* ==========================================================
   5. 引用  气泡下方 · 圆形小头像在左 · 后面是 名字：内容
            对方:左侧 L 形细弧(竖长横短)
            我方:右侧镜像
   ========================================================== */
.msg-reply-block{ display:none !important; }
.msg-reply-block-detached{
  display:flex !important; order:0 !important;
  flex-flow:row nowrap !important; align-items:center !important; gap:5px !important;
  position:relative !important; box-sizing:border-box !important;
  width:fit-content !important; min-width:0 !important; max-width:62vw !important;
  max-height:none !important;
  margin:4px 0 0 0 !important; padding:10px 0 0 !important;
  background:transparent !important;
  border:0 !important; border-left:0 !important; border-radius:0 !important;
  box-shadow:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  transform:none !important; clip-path:none !important; opacity:1 !important;
  white-space:nowrap !important; overflow:visible !important;
  font-family:var(--ap-font) !important;
}
.msg-reply-detached-them{ align-self:flex-start !important; margin-left:0 !important; margin-right:auto !important; padding-left:22px !important; }
.msg-reply-detached-me{ align-self:flex-end !important; margin-left:auto !important; margin-right:22px !important; padding-right:0 !important; }
.msg-reply-block-detached::after{
  content:"" !important; order:-1 !important; position:static !important;
  flex:0 0 16px !important; width:16px !important; height:16px !important;
  border-radius:50% !important; border:1px solid var(--ap-line) !important;
  background-color:var(--ap-soft) !important; background-size:cover !important; background-position:center !important;
  pointer-events:none !important;
}
.msg-reply-detached-me::after{ background-image:var(--char-avatar) !important; }
.msg-reply-detached-them::after{ background-image:var(--user-avatar) !important; }
.msg-reply-block-detached::before{
  content:"" !important; position:absolute !important;
  top:-4px !important; height:22px !important; width:8px !important;
  border:0 solid var(--ap-arc) !important; box-sizing:border-box !important;
  pointer-events:none !important; background:none !important;
}
.msg-reply-detached-them::before{
  left:10px !important; right:auto !important;
  border-left-width:1.2px !important; border-bottom-width:1.2px !important;
  border-bottom-left-radius:7px !important;
}
.msg-reply-detached-me::before{
  right:-12px !important; left:auto !important;
  border-right-width:1.2px !important; border-bottom-width:1.2px !important;
  border-bottom-right-radius:7px !important;
}
.msg-reply-block-detached > *{
  display:inline !important; flex:0 1 auto !important; min-width:0 !important;
  margin:0 !important; padding:0 !important; background:transparent !important;
  font-size:12px !important; line-height:16px !important; font-style:normal !important;
  color:var(--ap-ink-2) !important; text-shadow:none !important;
  white-space:nowrap !important;
}
.msg-reply-detached-name{ font-weight:600 !important; flex:0 0 auto !important; color:var(--ap-name) !important; }
.msg-reply-detached-text,
.msg-reply-detached-media{
  font-weight:400 !important; overflow:hidden !important; text-overflow:ellipsis !important;
}
.msg-reply-detached-media{ display:inline-flex !important; align-items:center !important; gap:4px !important; }
.msg-reply-block-detached :is(img, video, svg, canvas){
  display:inline-block !important; flex:0 0 18px !important;
  width:18px !important; height:18px !important;
  min-width:0 !important; max-width:18px !important; max-height:18px !important;
  object-fit:cover !important; border-radius:4px !important;
  margin:0 !important; padding:0 !important; vertical-align:middle !important;
}
.msg-bubble-wrapper:is(.is-last, .is-single):has(.msg-reply-block-detached){
  padding-bottom:calc(var(--ap-av) + 8px + var(--ap-group-gap)) !important;
}

/* ==========================================================
   6. 翻译  点气泡展开/收起 · 气泡下方无边框灰字
   ========================================================== */
.msg-translation-wrapper{
  position:absolute !important; inset:0 !important;
  height:auto !important; min-height:0 !important;
  margin:0 !important; padding:0 !important; line-height:0 !important;
  background:transparent !important; border:0 !important;
  overflow:visible !important; pointer-events:none !important; z-index:8 !important;
}
.msg-translation-wrapper .msg-translation-content{ display:none !important; }
.msg-translation-wrapper .msg-translation-btn{ pointer-events:auto !important; }
.msg-translation-btn{
  position:absolute !important; inset:0 !important;
  top:0 !important; left:0 !important; right:0 !important; bottom:0 !important;
  width:100% !important; height:100% !important; transform:none !important;
  display:block !important; margin:0 !important; padding:0 !important;
  background:transparent !important; border:0 !important; box-shadow:none !important;
  border-radius:inherit !important; outline:none !important;
  font-size:0 !important; line-height:0 !important; color:transparent !important; opacity:1 !important;
  overflow:hidden !important; cursor:pointer !important;
  -webkit-tap-highlight-color:transparent !important;
}
.msg-translation-btn > *{ opacity:0 !important; }
.msg-translation-btn::before,
.msg-translation-btn::after{ content:none !important; }

.msg-translation-detached{
  display:block !important; box-sizing:border-box !important;
  width:fit-content !important; min-width:0 !important; max-width:68vw !important;
  margin:4px 4px 0 !important;
}
.msg-translation-detached-them{ align-self:flex-start !important; }
.msg-translation-detached-me{ align-self:flex-end !important; }
.msg-bubble-wrapper:is(.is-last, .is-single):not(:has(.msg-reply-block-detached)) .msg-translation-detached{ margin-top:20px !important; }
.msg-translation-detached-content{
  position:relative !important; box-sizing:border-box !important;
  display:block !important; width:max-content !important; max-width:68vw !important; min-width:0 !important;
  padding:0 !important; margin:0 !important;
  background:transparent !important; border:0 !important; border-radius:0 !important;
  box-shadow:none !important; text-shadow:none !important;
  font:400 13px/18px var(--ap-font) !important; color:var(--ap-ink-2) !important;
  white-space:normal !important; word-break:break-word !important;
}
.msg-translation-detached-content *{ color:var(--ap-ink-2) !important; font-weight:400 !important; }
.msg-translation-detached-me .msg-translation-detached-content{ text-align:right !important; }
.msg-translation-detached-content::before,
.msg-translation-detached-content::after{ content:none !important; }
.msg-translation-detached-content del,
.msg-translation-detached-content s{ text-decoration:none !important; }

/* ==========================================================
   7. 思维链  无边框 · 淡灰文字「๑•̀ω•́๑」
   ========================================================== */
.nuo-thinking-wrap{ order:-3 !important; margin:0 0 3px 0 !important; padding:0 !important; }
.msg-content-stack > :has(> .nuo-thinking-btn),
.msg-content-stack > :has(.nuo-thinking-wrap){ order:-3 !important; }
.nuo-thinking-btn{
  display:inline-flex !important; align-items:center !important;
  width:auto !important; height:auto !important; min-height:0 !important;
  padding:0 2px !important; margin:0 !important;
  background:transparent !important; background-image:none !important;
  border:0 !important; border-radius:0 !important; box-shadow:none !important; outline:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  color:var(--ap-sub) !important; overflow:visible !important;
}
.nuo-thinking-btn::before,
.nuo-thinking-btn::after{ content:none !important; }
.nuo-thinking-btn .nuo-thinking-arrow,
.nuo-thinking-btn .nuo-thinking-icon{ display:none !important; }
.nuo-thinking-btn .nuo-thinking-label{
  font-size:0 !important; line-height:0 !important; color:transparent !important;
  display:inline-flex !important;
}
.nuo-thinking-btn .nuo-thinking-label::before{ content:none !important; }
.nuo-thinking-btn .nuo-thinking-label::after{
  content:"๑•̀ω•́๑" !important;
  font:400 12px/16px var(--ap-font); color:var(--ap-sub); letter-spacing:.5px;
}

/* ==========================================================
   8. 图片  两张 1:1 卡片叠放(后张固定图 · 前张是发送的图)
            实况层透明叠在前张图片上,不再盖白
   ========================================================== */
:is(.msg-image-card, .msg-image-wrapper){
  position:relative !important; box-sizing:border-box !important;
  width:206px !important; min-width:206px !important; max-width:none !important;
  height:190px !important; aspect-ratio:auto !important;
  padding:0 !important; margin:0 !important;
  border:0 !important; border-radius:0 !important;
  background:transparent !important; box-shadow:none !important; filter:none !important;
  overflow:visible !important;
}
/* 后面那张 */
:is(.msg-image-card, .msg-image-wrapper)::before{
  content:"" !important; position:absolute !important;
  right:0 !important; top:0 !important; left:auto !important; bottom:auto !important;
  width:128px !important; height:128px !important; box-sizing:border-box !important;
  border:5px solid var(--ap-frame) !important; border-radius:18px !important;
  background:var(--ap-img-back) no-repeat center / cover, var(--ap-soft) !important;
  box-shadow:0 6px 18px var(--ap-shadow), 0 0 0 1px var(--ap-line) !important;
  transform:rotate(3deg) !important;
  pointer-events:none !important; z-index:1 !important;
}
/* 前面那张(发送的图) */
:is(.msg-image-card, .msg-image-wrapper) > :not(.live-photo-badge):not(.live-photo-layer){
  position:absolute !important; left:0 !important; bottom:0 !important; top:auto !important; right:auto !important;
  width:138px !important; height:138px !important;
  max-width:none !important; max-height:none !important;
  margin:0 !important; padding:0 !important; transform:rotate(-2deg) !important;
  box-sizing:border-box !important;
  border:5px solid var(--ap-frame) !important; border-radius:18px !important; overflow:hidden !important;
  background:var(--ap-frame) !important;
  box-shadow:0 8px 22px var(--ap-shadow), 0 0 0 1px var(--ap-line) !important;
  filter:none !important; z-index:2 !important;
}
/* 实况层直接挂在外壳上:对齐前张卡片的图片区,透明不盖图 */
:is(.msg-image-card, .msg-image-wrapper) > .live-photo-layer{
  position:absolute !important; left:5px !important; bottom:5px !important; top:auto !important; right:auto !important;
  width:128px !important; height:128px !important; max-width:none !important; max-height:none !important;
  margin:0 !important; padding:0 !important; transform:rotate(-2deg) !important;
  border:0 !important; border-radius:13px !important; overflow:hidden !important;
  background:transparent !important; box-shadow:none !important; z-index:3 !important;
}
/* 实况层在前张卡片里面时:铺满卡片 */
:is(.msg-image-card, .msg-image-wrapper) > :not(.live-photo-badge) .live-photo-layer{
  position:absolute !important; inset:0 !important;
  left:0 !important; top:0 !important; right:0 !important; bottom:0 !important;
  width:100% !important; height:100% !important; max-width:none !important; max-height:none !important;
  margin:0 !important; padding:0 !important; transform:none !important;
  border:0 !important; border-radius:13px !important; overflow:hidden !important;
  background:transparent !important; box-shadow:none !important; z-index:3 !important;
}
:is(.msg-image-card, .msg-image-wrapper) img,
:is(.msg-image-card, .msg-image-wrapper) .live-photo-layer :is(img, video){
  display:block !important; width:100% !important; height:100% !important;
  max-width:none !important; max-height:none !important;
  aspect-ratio:1 / 1 !important; object-fit:cover !important;
  position:static !important; transform:none !important;
  border:0 !important; border-radius:13px !important; box-shadow:none !important; filter:none !important;
  background:transparent !important;
}
/* 右下小圆按钮(装饰) */
:is(.msg-image-card, .msg-image-wrapper)::after{
  content:"" !important; position:absolute !important;
  right:14px !important; bottom:16px !important; left:auto !important; top:auto !important;
  width:30px !important; height:30px !important; border-radius:50% !important;
  background:var(--ap-bubble) url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%238E8E93' stroke-opacity='.7' stroke-width='1.9' stroke-linecap='round' stroke-linejoin='round'><path d='M12 4v10M8 10l4 4 4-4'/><path d='M5 15v3a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-3'/></svg>") no-repeat center / 15px 15px !important;
  box-shadow:0 2px 8px var(--ap-shadow), 0 0 0 1px var(--ap-line) !important;
  pointer-events:none !important; z-index:4 !important;
}
/* LIVE 角标:半透明深色胶囊 · 白字 · 不压扁 */
#chat-detail-screen :is(.msg-image-card, .msg-image-wrapper) .live-photo-badge{
  position:absolute !important;
  left:13px !important; top:62px !important; bottom:auto !important; right:auto !important;
  width:auto !important; height:auto !important; min-width:0 !important; min-height:0 !important;
  max-width:none !important; max-height:none !important;
  margin:0 !important; padding:3px 7px 3px 5px !important; transform:none !important;
  display:inline-flex !important; align-items:center !important; gap:3px !important;
  border-radius:999px !important; border:0 !important;
  background:rgba(0,0,0,.38) !important;
  -webkit-backdrop-filter:blur(6px) !important; backdrop-filter:blur(6px) !important;
  box-shadow:none !important;
  font:600 10px/12px var(--ap-font) !important; letter-spacing:.6px !important;
  color:#FFFFFF !important; -webkit-text-fill-color:#FFFFFF !important; white-space:nowrap !important;
  z-index:5 !important; overflow:visible !important; pointer-events:auto !important;
}
#chat-detail-screen :is(.msg-image-card, .msg-image-wrapper) > :not(.live-photo-badge) .live-photo-badge{
  left:6px !important; top:6px !important; bottom:auto !important;
}
#chat-detail-screen :is(.msg-image-card, .msg-image-wrapper) .live-photo-badge *{
  width:auto !important; height:auto !important; max-width:none !important; max-height:none !important;
  margin:0 !important; padding:0 !important; border:0 !important; border-radius:0 !important;
  font:inherit !important; color:#FFFFFF !important; -webkit-text-fill-color:#FFFFFF !important;
  background:transparent !important; box-shadow:none !important;
  position:static !important; transform:none !important;
}
#chat-detail-screen :is(.msg-image-card, .msg-image-wrapper) .live-photo-badge :is(svg, img){
  width:12px !important; height:12px !important; flex:0 0 12px !important;
  color:#FFFFFF !important; stroke:currentColor;
}
/* 我方:整体镜像排列 */
.msg-me :is(.msg-image-card, .msg-image-wrapper)::before{ right:auto !important; left:0 !important; transform:rotate(-3deg) !important; }
.msg-me :is(.msg-image-card, .msg-image-wrapper) > :not(.live-photo-badge):not(.live-photo-layer){ left:auto !important; right:0 !important; transform:rotate(2deg) !important; }
.msg-me :is(.msg-image-card, .msg-image-wrapper) > .live-photo-layer{ left:auto !important; right:5px !important; transform:rotate(2deg) !important; }
.msg-me :is(.msg-image-card, .msg-image-wrapper)::after{ right:auto !important; left:14px !important; }
#chat-detail-screen .msg-me :is(.msg-image-card, .msg-image-wrapper) > .live-photo-badge{ left:auto !important; right:117px !important; }
.msg-content-stack:has(:is(.msg-image-card, .msg-image-wrapper))::after{ content:none !important; }

/* ==========================================================
   9. 通话卡  和气泡一样 · 只留文字
   ========================================================== */
.msg-videocall-card{
  position:relative !important; box-sizing:border-box !important;
  display:inline-flex !important; align-items:center !important; gap:6px !important;
  width:auto !important; min-width:0 !important; max-width:70vw !important;
  height:auto !important; min-height:0 !important;
  padding:var(--ap-pad) !important;
  border:1px solid var(--ap-line) !important; border-radius:var(--ap-r) !important;
  background:var(--ap-bubble) !important; box-shadow:none !important;
  overflow:visible !important;
}
.msg-videocall-card :is(svg, img, .msg-videocall-icon, [class*="rounded-full"]){ display:none !important; }
.msg-videocall-card *{
  min-height:0 !important; padding:0 !important; margin:0 !important;
  background:transparent !important; border:0 !important;
  font:400 16px/21px var(--ap-font) !important;
  color:var(--ap-ink) !important; text-shadow:none !important;
}
.msg-videocall-card > div{ display:inline-flex !important; flex-direction:row !important; align-items:center !important; gap:6px !important; }
.msg-videocall-card::before,
.msg-videocall-card::after{ content:none !important; }

/* ==========================================================
   10. 转账卡  推文卡:左侧圆形图标 · 金额 · 备注 · 右上状态
       (图标是半透明灰,日夜通用)
   ========================================================== */
#chat-detail-screen .msg-transfer-card,
.chat-detail-screen .msg-transfer-card{
  position:relative !important; box-sizing:border-box !important;
  display:flex !important; flex-direction:column !important; justify-content:center !important;
  width:230px !important; min-width:230px !important; max-width:72vw !important;
  height:auto !important; min-height:76px !important;
  padding:12px 14px 12px 64px !important;
  border:1px solid var(--ap-line) !important; border-radius:16px !important;
  box-shadow:none !important; filter:none !important;
  overflow:visible !important; text-align:left !important;
  background:
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'><circle cx='20' cy='20' r='19.5' fill='%238E8E93' fill-opacity='.08' stroke='%238E8E93' stroke-opacity='.22'/><g fill='none' stroke='%238E8E93' stroke-opacity='.7' stroke-width='1.7' stroke-linecap='round' stroke-linejoin='round'><path d='M13 16h14l-3.5-3.5'/><path d='M27 24H13l3.5 3.5'/></g></svg>") no-repeat 14px center / 38px 38px,
    var(--ap-bubble) !important;
}
#chat-detail-screen .msg-transfer-card:is(.msg-transfer-success, .msg-transfer-rejected, .msg-transfer-expired-card){
  background:
